type AnalyticsEventPayload = {
  eventType: string;
  page?: string;
  label?: string;
  metadata?: Record<string, unknown>;
};

type EventRecord = {
  id?: string | number;
  event_type?: string;
  page?: string;
  label?: string;
  metadata?: Record<string, unknown> | null;
  created_at?: string;
};

const SUPABASE_URL = process.env.REACT_APP_SUPABASE_URL;
const SUPABASE_ANON_KEY = process.env.REACT_APP_SUPABASE_ANON_KEY;
const EVENTS_TABLE = process.env.REACT_APP_SUPABASE_ANALYTICS_TABLE || 'admin_analytics_events';

function getHeaders() {
  if (!SUPABASE_URL || !SUPABASE_ANON_KEY) {
    return null;
  }

  return {
    apikey: SUPABASE_ANON_KEY,
    Authorization: `Bearer ${SUPABASE_ANON_KEY}`,
    'Content-Type': 'application/json',
    Prefer: 'return=minimal'
  };
}

export function isSupabaseAnalyticsEnabled() {
  return Boolean(SUPABASE_URL && SUPABASE_ANON_KEY);
}

export async function recordAdminAnalyticsEvent(payload: AnalyticsEventPayload) {
  const headers = getHeaders();
  if (!headers || !SUPABASE_URL) {
    return;
  }

  const body = {
    event_type: payload.eventType,
    page: payload.page || 'admin-analytics',
    label: payload.label || null,
    metadata: payload.metadata || {}
  };

  try {
    await fetch(`${SUPABASE_URL}/rest/v1/${EVENTS_TABLE}`, {
      method: 'POST',
      headers,
      body: JSON.stringify(body)
    });
  } catch (error) {
    console.warn('Supabase analytics event could not be recorded.', error);
  }
}

export async function fetchAdminAnalyticsEvents(limit = 30): Promise<EventRecord[]> {
  const headers = getHeaders();
  if (!headers || !SUPABASE_URL) {
    return [];
  }

  try {
    const response = await fetch(
      `${SUPABASE_URL}/rest/v1/${EVENTS_TABLE}?select=id,event_type,page,label,metadata,created_at&order=created_at.desc&limit=${limit}`,
      {
        method: 'GET',
        headers
      }
    );

    if (!response.ok) {
      throw new Error(`Supabase request failed with ${response.status}`);
    }

    return (await response.json()) as EventRecord[];
  } catch (error) {
    console.warn('Supabase analytics events could not be loaded.', error);
    return [];
  }
}
