import React from 'react';
import CatalogItemForm from './catalog/components/CatalogItemForm';
import CreatorAuthorityForm from './catalog/components/CreatorAuthorityForm';
import CollectionsCatalog from './catalog/components/CollectionsCatalog';
import CreatorsListViewer from './catalog/components/creators_list_viewer';
import AdminAnalytics from './catalog/components/admin_analytics';

type ViewKey = 'collections' | 'catalog' | 'list_creators' | 'creators' | 'admin';
const ADMIN_HASH = '#admin';
const ADMIN_ACCESS_KEY = process.env.REACT_APP_ADMIN_ACCESS_KEY;

function App() {
  const getInitialView = React.useCallback((): ViewKey => {
    return window.location.hash === ADMIN_HASH ? 'admin' : 'collections';
  }, []);
  const [currentView, setCurrentView] = React.useState<ViewKey>(getInitialView);
  const [adminUnlocked, setAdminUnlocked] = React.useState<boolean>(false);

  const navItems: Array<{ key: ViewKey; label: string }> = [
    { key: 'collections', label: 'Collections' },
    { key: 'catalog', label: 'Catalog Items' },
    { key: 'list_creators', label: 'Creators List' },
    { key: 'creators', label: 'Creators' }
  ];

  React.useEffect(() => {
    const syncFromHash = () => {
      if (window.location.hash === ADMIN_HASH) {
        setCurrentView('admin');
      } else {
        setCurrentView((prev) => (prev === 'admin' ? 'collections' : prev));
      }
    };

    window.addEventListener('hashchange', syncFromHash);
    syncFromHash();

    return () => window.removeEventListener('hashchange', syncFromHash);
  }, []);

  React.useEffect(() => {
    if (currentView !== 'admin') {
      setAdminUnlocked(false);
      return;
    }

    const entered = window.prompt('Admin access key');
    const expected = ADMIN_ACCESS_KEY || 'rarebooks-admin';

    if (entered && entered === expected) {
      setAdminUnlocked(true);
      return;
    }

    setAdminUnlocked(false);
    window.location.hash = '';
    setCurrentView('collections');
  }, [currentView]);

  const closeAdmin = () => {
    setAdminUnlocked(false);
    window.location.hash = '';
    setCurrentView('collections');
  };

  return (
    <div className="App min-h-screen bg-stone-100">
      <nav className="sticky top-0 z-20 border-b border-amber-950/20 bg-amber-900 text-white shadow-sm">
        <div className="flex flex-wrap items-center justify-between gap-2 px-4 py-3">
          <div className="flex flex-wrap gap-2">
          {navItems.map((item) => (
            <button
              key={item.key}
              onClick={() => setCurrentView(item.key)}
              className={[
                'rounded-full px-4 py-2 text-sm font-medium transition',
                currentView === item.key
                  ? 'bg-white text-amber-900'
                  : 'bg-transparent text-amber-50 hover:bg-white/10'
              ].join(' ')}
            >
              {item.label}
            </button>
          ))}
          </div>
          <div className="flex items-center gap-2">
            {currentView === 'admin' && adminUnlocked && (
              <button
                onClick={closeAdmin}
                className="rounded-full border border-white/20 px-4 py-2 text-sm font-medium text-amber-50 transition hover:bg-white/10"
              >
                Exit Admin
              </button>
            )}
          </div>
        </div>
      </nav>

      {currentView === 'collections' && <CollectionsCatalog />}
      {currentView === 'catalog' && <CatalogItemForm />}
      {currentView === 'list_creators' && <CreatorsListViewer />}
      {currentView === 'creators' && <CreatorAuthorityForm />}
      {currentView === 'admin' && adminUnlocked && <AdminAnalytics />}
    </div>
  );
}

export default App;
